SELECT customers.customer_name, sum(orders.sales) as celkovy_predaj, avg(orders.discount) as priemerna_zlava, count(orders.order_id) as pocet_obj, case when sum(orders.sales) > 2500 then 'VIP' else 'Regular' END AS customer_type FROM customers  JOIN orders ON customers.customer_id = orders.customer_id GROUP BY customers.customer_id, customers.customer_name order by sum(orders.sales) DESC